        )
        add_axis_moves(source_row, gap_row, "U", "D")
        add_axis_moves(source_col, target_col, "L", "R")
        add_axis_moves(gap_row, target_row, "U", "D")
    else:
        add_axis_moves(source_col, target_col, "L", "R")
        add_axis_moves(source_row, target_row, "U", "D")

    if len(route) != len(cols):
